package com.example.streamnest

/** Release notes shown in Help & Settings > Update Log. Newest first. Add a new entry with every version. */
data class Release(val version: String, val date: String, val title: String, val changes: List<String>)

/** Each app shows its own releases: the TV app the "TV …" entries, the phone app the others. */
val Changelog: List<Release> = AllReleases.filter { it.version.startsWith("TV") == BuildConfig.IS_TV }.ifEmpty { AllReleases }

/**
 * What users see in Update Log: features and improvements in plain words — no servers, sources, addons or technical
 * details. The full technical changelog ([Changelog]) is in Developer's Corner.
 */
val UserLog: List<Release> get() = UserReleases.filter { it.version.startsWith("TV") == BuildConfig.IS_TV }.ifEmpty { UserReleases }

